const registros = $input.all().map(item => item.json);

// ===============================
// FUNÇÕES AUXILIARES
// ===============================

function converterData(data) {
  if (!data) return null;

  const [dia, mes, ano] = String(data).split("/");

  if (!dia || !mes || !ano) return null;

  return new Date(
    Number(ano),
    Number(mes) - 1,
    Number(dia)
  );
}

function normalizar(v) {
  return String(v || "").trim();
}

function chave(v) {
  return normalizar(v)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

function tituloNome(v) {
  const particulas = new Set(["da","de","do","das","dos","e"]);
  return normalizar(v).toLowerCase().split(/\s+/).map((p,i) =>
    i > 0 && particulas.has(p) ? p : p.charAt(0).toUpperCase() + p.slice(1)
  ).join(" ");
}

function tituloMotivo(v) {
  const t = normalizar(v);
  return t ? t.charAt(0).toUpperCase() + t.slice(1).toLowerCase() : "";
}

// ===============================
// DATA ATUAL
// ===============================

const agora = new Date();

const hoje = agora.toLocaleDateString("pt-BR", {
  timeZone: "America/Recife"
});

const inicioSemana = new Date();
inicioSemana.setHours(0, 0, 0, 0);
inicioSemana.setDate(inicioSemana.getDate() - 6);

// ===============================
// TOTAL GERAL
// ===============================

const total = registros.length;

// ===============================
// REGISTROS DE HOJE
// ===============================

const registrosHoje = registros.filter(r =>
  normalizar(r.data_saida) === hoje
);

const totalHoje = registrosHoje.length;

// ===============================
// REGISTROS DOS ÚLTIMOS 7 DIAS
// ===============================

const registrosSemana = registros.filter(r => {
  const data = converterData(r.data_saida);

  if (!data) return false;

  data.setHours(0, 0, 0, 0);

  return data >= inicioSemana && data <= agora;
});

const totalSemana = registrosSemana.length;

// ===============================
// RANKING DE TURMAS
// ===============================

const contagemTurmas = {};

registrosSemana.forEach(r => {
  const turma = normalizar(r.turma) || "Não informado";

  contagemTurmas[turma] =
    (contagemTurmas[turma] || 0) + 1;
});

const porTurma = Object.entries(contagemTurmas)
  .map(([turma, total]) => ({
    turma,
    total
  }))
  .sort((a, b) => b.total - a.total);

const turmaMaisSaidas =
  porTurma[0]?.turma || "Nenhuma";

// ===============================
// RANKING DE ALUNOS
// ===============================

const alunos = {};

registrosSemana.forEach(r => {
  const nomeOriginal = normalizar(r.nome_aluno);
  const id = chave(nomeOriginal);

  if (!id) return;

  if (!alunos[id]) {
    alunos[id] = {
      nome_aluno: tituloNome(nomeOriginal),
      total: 0,
      turma: normalizar(r.turma).toUpperCase()
    };
  }

  alunos[id].total++;
});

const rankingAlunos = Object.values(alunos)
  .map(dados => ({
    nome_aluno: dados.nome_aluno,
    turma: dados.turma || "Não informado",
    total: dados.total
  }))
  .sort((a, b) => b.total - a.total);

// ===============================
// MOTIVOS MAIS FREQUENTES
// ===============================

const contagemMotivos = {};

registrosSemana.forEach(r => {
  const original = normalizar(r.motivo) || "Não informado";
  const id = chave(original) || "nao informado";

  if (!contagemMotivos[id]) {
    contagemMotivos[id] = {
      motivo: original === "Não informado" ? original : tituloMotivo(original),
      total: 0
    };
  }

  contagemMotivos[id].total++;
});

const motivos = Object.values(contagemMotivos)
  .sort((a, b) => b.total - a.total);

// ===============================
// DIA MAIS MOVIMENTADO
// ===============================

const contagemDias = {};

registrosSemana.forEach(r => {
  const data = normalizar(r.data_saida);

  if (!data) return;

  contagemDias[data] =
    (contagemDias[data] || 0) + 1;
});

const porDia = Object.entries(contagemDias)
  .map(([data, total]) => ({
    data,
    total
  }))
  .sort((a, b) => b.total - a.total);

// ===============================
// HORÁRIO DE PICO
// ===============================

const contagemHoras = {};

registrosSemana.forEach(r => {
  const horario = normalizar(r.horario_saida);

  if (!horario) return;

  const hora = Number(horario.split(":")[0]);

  if (Number.isNaN(hora)) return;

  const inicio = String(hora).padStart(2, "0");
  const fim = String((hora + 1) % 24).padStart(2, "0");

  const faixa = `${inicio}h–${fim}h`;

  contagemHoras[faixa] =
    (contagemHoras[faixa] || 0) + 1;
});

const porHora = Object.entries(contagemHoras)
  .map(([faixa, total]) => ({
    faixa,
    total
  }))
  .sort((a, b) => b.total - a.total);

// ===============================
// REGISTROS RECENTES
// ===============================

const recentes = [...registros]
  .sort((a, b) => {
    const dataA = converterData(a.data_saida);
    const dataB = converterData(b.data_saida);

    if (!dataA || !dataB) return 0;

    const horaA =
      String(a.horario_saida || "00:00")
        .split(":");

    const horaB =
      String(b.horario_saida || "00:00")
        .split(":");

    dataA.setHours(
      Number(horaA[0] || 0),
      Number(horaA[1] || 0)
    );

    dataB.setHours(
      Number(horaB[0] || 0),
      Number(horaB[1] || 0)
    );

    return dataB - dataA;
  })
  .slice(0, 5)
  .map(r => ({
    nome_aluno: r.nome_aluno,
    turma: r.turma,
    data_saida: r.data_saida,
    horario_saida: r.horario_saida,
    responsavel: r.responsavel,
    motivo: r.motivo,
    status: r.status
  }));

// ===============================
// RESPOSTA FINAL
// ===============================

return [{
  json: {
    total,
    hoje: totalHoje,
    semana: totalSemana,

    turma_mais_saidas: turmaMaisSaidas,

    por_turma: porTurma,

    ranking_alunos: rankingAlunos,

    motivos,

    por_dia: porDia,

    por_hora: porHora,

    recentes
  }
}];
